package com.gamingevents.controller; import com.gamingevents.dto.AuthDtos.*; import com.gamingevents.service.AuthService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController { final AuthService service; public AuthController(AuthService s){service=s;} @PostMapping("/register") public TokenResponse register(@Valid @RequestBody RegisterRequest r){return service.register(r);}@PostMapping("/login") public TokenResponse login(@Valid @RequestBody LoginRequest r){return service.login(r);}@GetMapping("/me") public CurrentUserResponse me(Authentication a){return service.current(a.getName());} }
